export type RollbackView = { snapshotId: string; restoredAt: number; interruptionMs: number }
/**
 * Aggregate result of [`mcp_rotate_token`]: how many projects were touched
 * and how many of those failed to rewrite. Mirrors the relevant fields of
 * [`install::SweepReport`] without leaking the new token.
 */
export type RotateReport = { 
/**
 * Imported projects considered (i.e. slug present and repo on disk).
 */
linkedProjects: number; 
/**
 * Subset of [`Self::linked_projects`] whose rewrite failed.
 */
failed: number }
/**
 * Response returned to the frontend after sharing a project
 */
export type ShareResponse = { url: string }
export type SnapshotId = string
export type SnapshotRecord = { id: SnapshotId; projectId: ProjectId; label: string | null; takenAt: number; sizeBytes: number }
/**
 * An app as listed by the registry's store catalog.
 */
export type StoreApp = { manifest: Manifest }
export type UpdateInfo = { version: string; currentVersion: string; notes: string | null; date: string | null }
/**
 * Emitted on the `vm-image-progress` Tauri event. Byte counts are over the
 * compressed payload (matches what the user sees as MB/s).
 */
export type VmImageProgress = { phase: "started"; total: number } | { phase: "downloading"; downloaded: number; total: number } | { phase: "verifying" } | { phase: "decompressing" } | { phase: "finished" }
/**
 * Whether the local image is current, plus size hints for the welcome screen.
 */
export type VmImageStatus = { needed: boolean; installedVersion: string | null; targetVersion: string | null; compressedSizeBytes: number | null; uncompressedSizeBytes: number | null }

/** tauri-specta globals **/

import {
	invoke as TAURI_INVOKE,
	Channel as TAURI_CHANNEL,
} from "@tauri-apps/api/core";
import * as TAURI_API_EVENT from "@tauri-apps/api/event";
import { type WebviewWindow as __WebviewWindow__ } from "@tauri-apps/api/webviewWindow";

type __EventObj__<T> = {
	listen: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.listen<T>>;
	once: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.once<T>>;
	emit: null extends T
		? (payload?: T) => ReturnType<typeof TAURI_API_EVENT.emit>
		: (payload: T) => ReturnType<typeof TAURI_API_EVENT.emit>;
};

export type Result<T, E> =
	| { status: "ok"; data: T }
	| { status: "error"; error: E };

function __makeEvents__<T extends Record<string, any>>(
	mappings: Record<keyof T, string>,
) {
	return new Proxy(
		{} as unknown as {
			[K in keyof T]: __EventObj__<T[K]> & {
				(handle: __WebviewWindow__): __EventObj__<T[K]>;
			};
		},
		{
			get: (_, event) => {
				const name = mappings[event as keyof T];

				return new Proxy((() => {}) as any, {
					apply: (_, __, [window]: [__WebviewWindow__]) => ({
						listen: (arg: any) => window.listen(name, arg),
						once: (arg: any) => window.once(name, arg),
						emit: (arg: any) => window.emit(name, arg),
					}),
					get: (_, command: keyof __EventObj__<any>) => {
						switch (command) {
							case "listen":
								return (arg: any) => TAURI_API_EVENT.listen(name, arg);
							case "once":
								return (arg: any) => TAURI_API_EVENT.once(name, arg);
							case "emit":
								return (arg: any) => TAURI_API_EVENT.emit(name, arg);
						}
					},
				});
			},
		},
	);
}
